using System.Diagnostics;
using System.Text;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using Modeller.Core;
namespace Modeller.Application;

public sealed class GitRepository:SnapshotRepository
{
    private readonly string directory,objects,branch,prefix,remote;private readonly bool flat;private string? head;
    public GitRepository(string root,string? configuredRemote=null):base(root){directory=System.IO.Path.Combine(root,"git");objects=System.IO.Path.Combine(directory,"objects.git");Safe(directory);Directory.CreateDirectory(directory);branch=Environment.GetEnvironmentVariable("MODEL_GIT_BRANCH")??"main";BranchName(branch);prefix=Environment.GetEnvironmentVariable("MODEL_GIT_CONTENT_PATH")??"";if(prefix!=""&&!Regex.IsMatch(prefix,"^[A-Za-z0-9][A-Za-z0-9_/-]*$")||prefix.Contains("//",StringComparison.Ordinal)||prefix.Contains("..",StringComparison.Ordinal)||prefix.EndsWith('/'))throw new ProcessingException("INVALID_GIT_CONTENT_PATH");if(prefix!="")prefix+="/";flat=Environment.GetEnvironmentVariable("MODEL_GIT_LAYOUT")=="flat";remote=configuredRemote??Environment.GetEnvironmentVariable("MODEL_GIT_REMOTE_URL")??"";if(remote!=""&&!Regex.IsMatch(remote,"^(?:https://[A-Za-z0-9.-]+(?::[0-9]+)?/[A-Za-z0-9_./-]+|[A-Za-z0-9_-]+@[A-Za-z0-9.-]+:[A-Za-z0-9_./-]+|ssh://[A-Za-z0-9_-]+@[A-Za-z0-9.-]+(?::[0-9]+)?/[A-Za-z0-9_./-]+)$"))throw new ProcessingException("INVALID_GIT_REMOTE");}
    public string Remote=>remote;
    private readonly System.Diagnostics.Stopwatch elapsed=System.Diagnostics.Stopwatch.StartNew();
    public static void BranchName(string name){if(name.Length is <1 or >200||name.StartsWith('-')||!Regex.IsMatch(name,"^[A-Za-z0-9][A-Za-z0-9_./-]*$")||name.Contains("..",StringComparison.Ordinal)||name.Contains("//",StringComparison.Ordinal)||name.EndsWith('/')||name.EndsWith(".lock",StringComparison.Ordinal)||name.EndsWith('.'))throw new ProcessingException("INVALID_GIT_BRANCH");}
    private (int Code,byte[] Bytes) Run(IEnumerable<string> arguments,byte[]? input=null,Dictionary<string,string>? environment=null,bool check=true,bool bare=true){
        if(elapsed.Elapsed>TimeSpan.FromSeconds(120))throw new ProcessingException("GIT_TIMEOUT");var start=new ProcessStartInfo("git"){RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,UseShellExecute=false,WorkingDirectory=directory};foreach(var a in new[]{"-c","core.hooksPath=/dev/null","-c","protocol.ext.allow=never","-c","protocol.file.allow=never"})start.ArgumentList.Add(a);if(bare)start.ArgumentList.Add("--git-dir="+objects);foreach(var a in arguments)start.ArgumentList.Add(a);
        foreach(var key in start.Environment.Keys.Where(k=>k.StartsWith("GIT_",StringComparison.Ordinal)).ToArray())start.Environment.Remove(key);
        start.Environment["GIT_CONFIG_NOSYSTEM"]="1";start.Environment["GIT_CONFIG_GLOBAL"]="/dev/null";start.Environment["GIT_TERMINAL_PROMPT"]="0";
        foreach(var key in new[]{"GIT_AUTHOR_NAME","GIT_COMMITTER_NAME"})start.Environment[key]=Environment.GetEnvironmentVariable("MODEL_GIT_AUTHOR_NAME")??"Clinical Modeller";foreach(var key in new[]{"GIT_AUTHOR_EMAIL","GIT_COMMITTER_EMAIL"})start.Environment[key]=Environment.GetEnvironmentVariable("MODEL_GIT_AUTHOR_EMAIL")??"modeller@localhost";
        var ssh="ssh -F /dev/null -o BatchMode=yes -o IdentitiesOnly=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=10";var keyFile=Environment.GetEnvironmentVariable("MODEL_GIT_SSH_KEY_FILE")??"";var hosts=Environment.GetEnvironmentVariable("MODEL_GIT_KNOWN_HOSTS_FILE")??"";
        if(keyFile!=""||hosts!=""){foreach(var p in new[]{keyFile,hosts}){if(!System.IO.Path.IsPathFullyQualified(p)||!File.Exists(p)||p.Any(char.IsControl))throw new ProcessingException("GIT_CREDENTIAL_FILE_UNREADABLE");Safe(p);}static string Q(string s)=>"'"+s.Replace("'","'\"'\"'",StringComparison.Ordinal)+"'";ssh+=" -i "+Q(keyFile)+" -o UserKnownHostsFile="+Q(hosts);}start.Environment["GIT_SSH_COMMAND"]=ssh;if(environment is not null)foreach(var(k,v)in environment)start.Environment[k]=v;
        using var process=new Process{StartInfo=start};process.Start();using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(Math.Clamp(int.TryParse(Environment.GetEnvironmentVariable("MODEL_GIT_TIMEOUT"),out var seconds)?seconds:30,1,120)));
        async Task<byte[]> Read(Stream stream){using var output=new MemoryStream();var buffer=new byte[16384];int n;while((n=await stream.ReadAsync(buffer,timeout.Token))>0){if(output.Length+n>33554432)throw new ProcessingException("GIT_OUTPUT_LIMIT");output.Write(buffer,0,n);}return output.ToArray();}
        async Task<(int,byte[])> Execute(){var output=Read(process.StandardOutput.BaseStream);var error=Read(process.StandardError.BaseStream);try{if(input is not null)await process.StandardInput.BaseStream.WriteAsync(input,timeout.Token);process.StandardInput.Close();await process.WaitForExitAsync(timeout.Token);var bytes=await output;await error;return(process.ExitCode,bytes);}catch{try{process.Kill(true);}catch(InvalidOperationException){}try{await Task.WhenAll(output,error);}catch{}throw;}}
        (int code,byte[] bytes) result;try{result=Execute().GetAwaiter().GetResult();}catch(OperationCanceledException){throw new ProcessingException("GIT_TIMEOUT");}if(check&&result.code!=0)throw new ProcessingException("GIT_OPERATION_FAILED");return result;
    }
    private string Git(params string[] args)=>Encoding.UTF8.GetString(Run(args).Bytes).Trim();
    private T Locked<T>(Func<T> operation,bool write=false){using var gate=new FileGate(System.IO.Path.Combine(directory,"repository.lock"));Safe(objects);if(!Directory.Exists(objects))Run(["init","--bare","--initial-branch="+branch,objects],bare:false);var revision=Run(["rev-parse","--verify","refs/heads/"+branch],check:false);head=revision.Code==0?Encoding.UTF8.GetString(revision.Bytes).Trim():null;
        if(remote!=""){
            var existing=Run(["remote","get-url","origin"],check:false);if(existing.Code!=0)Git("remote","add","origin",remote);else if(Encoding.UTF8.GetString(existing.Bytes).Trim()!=remote)throw new ProcessingException("GIT_REMOTE_CHANGED_USE_NEW_PATH");var stamp=System.IO.Path.Combine(directory,"last-sync");var interval=int.TryParse(Environment.GetEnvironmentVariable("MODEL_GIT_SYNC_SECONDS"),out var sync)?Math.Clamp(sync,0,300):5;
            if(write||!File.Exists(stamp)||DateTime.UtcNow-File.GetLastWriteTimeUtc(stamp)>TimeSpan.FromSeconds(interval)){
                var upstream=Run(["ls-remote","--exit-code","--heads","origin","refs/heads/"+branch],check:false);if(upstream.Code==2&&head is not null)throw new ProcessingException("GIT_REMOTE_BRANCH_REMOVED");if(upstream.Code is not(0 or 2))throw new ProcessingException("GIT_REMOTE_UNAVAILABLE");if(upstream.Code==0){var sha=Encoding.UTF8.GetString(upstream.Bytes).Split('\t')[0];if(sha!=head){Git("fetch","--no-tags","origin","+refs/heads/"+branch+":refs/remotes/origin/"+branch);var next=Git("rev-parse","refs/remotes/origin/"+branch);Tree(next);if(head is not null&&Run(["merge-base","--is-ancestor",head,next],check:false).Code!=0)throw new ProcessingException("GIT_REMOTE_DIVERGED");Git("update-ref","refs/heads/"+branch,next,head??new string('0',40));head=next;}}File.WriteAllText(stamp,"synced");
            }
        }if(head is not null)Tree(head);return operation();
    }
    private Dictionary<string,long> Tree(string at){var output=Encoding.UTF8.GetString(Run(["ls-tree","-rlz","--full-tree",at]).Bytes);var result=new Dictionary<string,long>(StringComparer.Ordinal);long total=0;foreach(var record in output.Split('\0',StringSplitOptions.RemoveEmptyEntries)){var match=Regex.Match(record,"^(100644|100755) blob [a-f0-9]+ +([0-9]+)\\t([^\\x00-\\x1f\\x7f]+)$");if(!match.Success)throw new ProcessingException("GIT_UNSAFE_TREE");var size=long.Parse(match.Groups[2].Value,System.Globalization.CultureInfo.InvariantCulture);total+=size;if(size>2097152||total>33554432||result.Count>=10000)throw new ProcessingException("GIT_TREE_SIZE_LIMIT");var path=match.Groups[3].Value;if(path.Split('/').Any(s=>s is "." or "..")||path.Contains('\\'))throw new ProcessingException("GIT_UNSAFE_TREE");result[path]=size;}return result;}
    private string Head()=>head??throw new ProcessingException("PROJECT_NOT_FOUND");
    private void Reachable(string revision){if(!Regex.IsMatch(revision,"^[a-f0-9]{40}$")||head is null||Run(["merge-base","--is-ancestor",revision,head],check:false).Code!=0)throw new ProcessingException("VERSION_NOT_FOUND");}
    private string Prefix(string id){if(!Regex.IsMatch(id,"^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$"))throw new ProcessingException("INVALID_PROJECT_ID");return prefix+(id=="default"?"":"projects/"+id+"/");}
    private string Storage(string id,string path){ArtifactPath(path);if(flat&&(path.StartsWith("archetypes/",StringComparison.Ordinal)||path.StartsWith("templates/",StringComparison.Ordinal))){var name=path[(path.IndexOf('/')+1)..];if(name.Contains('/')||Logical(name)!=path)throw new ProcessingException("GIT_FLAT_LAYOUT_REQUIRES_NATIVE_FILENAME");return Prefix(id)+name;}return Prefix(id)+path;}
    private string? Logical(string path){if(flat){if(path.StartsWith("archetypes/",StringComparison.Ordinal)||path.StartsWith("templates/",StringComparison.Ordinal))return null;if(!path.Contains('/')){if(Regex.IsMatch(path,"\\.(?:adl|adls|adlf|a\\.json)$"))path="archetypes/"+path;else if(Regex.IsMatch(path,"\\.(?:t\\.json|oet|opt)$"))path="templates/"+path;}}try{ArtifactPath(path);return path;}catch(ProcessingException){return null;}}
    private string Meta(string id,string path)=>Prefix(id)+".modelling/artifacts/"+Data.Hash(path)+".json";
    private byte[] Blob(string at,string path){if(!Tree(at).ContainsKey(path))throw new ProcessingException("ARTIFACT_NOT_FOUND");return Run(["show",at+":"+path]).Bytes;}
    private string Last(string at,params string[] paths)=>Encoding.UTF8.GetString(Run(new[]{"log","-1","--format=%H",at,"--"}.Concat(paths)).Bytes).Trim();
    private JsonObject ProjectCore(string id){var path=Prefix(id)+".modelling/project.json";if(head is not null&&Tree(head).ContainsKey(path)){var data=JsonNode.Parse(Blob(head,path)) as JsonObject??throw new ProcessingException("GIT_INVALID_PROJECT");if(S(data,"id")!=id||S(data,"status") is not("ACTIVE" or "ARCHIVED"))throw new ProcessingException("GIT_INVALID_PROJECT");data["revision"]=Last(head,path);data["provider"]="git";return data;}if(id=="default"&&head is not null&&Tree(head).Keys.Any(p=>p.StartsWith(prefix,StringComparison.Ordinal)&&Logical(p[prefix.Length..]) is not null))return new JsonObject{["id"]="default",["name"]="Git model repository",["description"]="Imported model content",["status"]="ACTIVE",["revision"]=head,["provider"]="git"};throw new ProcessingException("PROJECT_NOT_FOUND");}
    private static string S(JsonObject o,string k)=>KnowledgeCorpus.Text(o,k);
    private JsonObject ArtifactCore(string id,string path,string at,bool historical=false){var full=Storage(id,path);var meta=Meta(id,path);var tree=Tree(at);var deleted=!tree.ContainsKey(full);var contentAt=at;if(deleted){if(!historical)throw new ProcessingException("ARTIFACT_NOT_FOUND");contentAt=Git("rev-parse","--verify",at+"^");if(!Tree(contentAt).ContainsKey(full))throw new ProcessingException("VERSION_NOT_FOUND");}var bytes=Blob(contentAt,full);string? content=null;try{content=new UTF8Encoding(false,true).GetString(bytes);}catch(DecoderFallbackException){if(!path.StartsWith("originals/",StringComparison.Ordinal))throw new ProcessingException("GIT_INVALID_TEXT");}var metadata=tree.ContainsKey(meta)?JsonNode.Parse(Blob(at,meta))?["metadata"]?.DeepClone() as JsonObject??new JsonObject():new JsonObject();var revision=Last(at,full,meta);var item=new JsonObject{["path"]=path,["content"]=content,["metadata"]=metadata,["status"]=deleted?"DELETED":"DRAFT",["revision"]=revision,["sha256"]=Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(bytes)),["updated_at"]=Git("show","-s","--format=%cI",revision),["provider"]="git"};if(path.StartsWith("originals/",StringComparison.Ordinal)){if(content?.Contains('\0')==true)content=null;item["content"]=content;item["content_base64"]=content is null?Convert.ToBase64String(bytes):null;item["content_encoding"]=content is null?"base64":"utf8";item["size_bytes"]=bytes.Length;}return item;}
    private void Commit(Dictionary<string,byte[]> changes,string message){var index=System.IO.Path.Combine(directory,"index-"+Guid.NewGuid().ToString("N"));var environment=new Dictionary<string,string>{["GIT_INDEX_FILE"]=index};try{Run(head is null?["read-tree","--empty"]:["read-tree",head],environment:environment);foreach(var(path,bytes)in changes){var blob=Encoding.UTF8.GetString(Run(["hash-object","-w","--stdin"],bytes).Bytes).Trim();Run(["update-index","--add","--cacheinfo","100644,"+blob+","+path],environment:environment);}var tree=Encoding.UTF8.GetString(Run(["write-tree"],environment:environment).Bytes).Trim();var next=Encoding.UTF8.GetString(Run(new[]{"commit-tree",tree}.Concat(head is null?[]:new[]{"-p",head}),Encoding.UTF8.GetBytes(message+"\n")).Bytes).Trim();Tree(next);if(remote!="")Git("push","origin",next+":refs/heads/"+branch);Git("update-ref","refs/heads/"+branch,next,head??new string('0',40));head=next;}finally{foreach(var file in new[]{index,index+".lock"})if(File.Exists(file))File.Delete(file);}}
    public override JsonArray List()=>Locked(()=>{var ids=new HashSet<string>(StringComparer.Ordinal);if(head is not null)foreach(var file in Tree(head).Keys.Where(f=>f.StartsWith(prefix,StringComparison.Ordinal))){var p=file[prefix.Length..];if(p==".modelling/project.json"||Logical(p) is not null)ids.Add("default");var m=Regex.Match(p,"^projects/([A-Za-z0-9_-]+)/.modelling/project.json$");if(m.Success)ids.Add(m.Groups[1].Value);}return new JsonArray(ids.Order(StringComparer.Ordinal).Select(id=>(JsonNode)ProjectCore(id)).ToArray());});
    public override JsonObject Project(string id)=>Locked(()=>ProjectCore(id));
    public override JsonArray Artifacts(string id)=>Locked(()=>{ProjectCore(id);var p=Prefix(id);return new JsonArray(Tree(Head()).Keys.Where(f=>f.StartsWith(p,StringComparison.Ordinal)).Select(f=>Logical(f[p.Length..])).Where(f=>f is not null).Select(f=>(JsonNode)ArtifactCore(id,f!,Head())).ToArray());});
    public override JsonObject Create(string id,string name,string description)=>Locked(()=>{try{ProjectCore(id);throw new ProcessingException("PROJECT_ALREADY_EXISTS");}catch(ProcessingException e)when(e.Code=="PROJECT_NOT_FOUND"){}if(string.IsNullOrWhiteSpace(name)||name.Length>200||description.Length>10000)throw new ProcessingException("INVALID_PROJECT");var now=DateTimeOffset.UtcNow.ToString("O");var project=new JsonObject{["id"]=id,["name"]=name,["description"]=description,["status"]="ACTIVE",["created_at"]=now,["updated_at"]=now};Commit(new Dictionary<string,byte[]>{[Prefix(id)+".modelling/project.json"]=Encoding.UTF8.GetBytes(project.ToJsonString())},"Create modelling project "+id);return ProjectCore(id);},true);
    public override JsonObject Archive(string id,string expectedRevision)=>Locked(()=>{var project=ProjectCore(id);if(S(project,"revision")!=expectedRevision)throw new ProcessingException("REVISION_CONFLICT");project["status"]="ARCHIVED";project["updated_at"]=DateTimeOffset.UtcNow.ToString("O");project.Remove("revision");project.Remove("provider");Commit(new Dictionary<string,byte[]>{[Prefix(id)+".modelling/project.json"]=Encoding.UTF8.GetBytes(project.ToJsonString())},"Archive modelling project "+id);return ProjectCore(id);},true);
    public override JsonObject Artifact(string id,string path,string? revision=null)=>Locked(()=>{ProjectCore(id);if(revision is not null)Reachable(revision);return ArtifactCore(id,path,revision??Head(),revision is not null);});
    public override JsonArray History(string id,string path)=>Locked(()=>{ProjectCore(id);var output=Git("log","--format=%H","--max-count=1001",Head(),"--",Storage(id,path),Meta(id,path));var revisions=output.Split('\n',StringSplitOptions.RemoveEmptyEntries);if(revisions.Length>1000)throw new ProcessingException("GIT_HISTORY_LIMIT");return new JsonArray(revisions.Select(r=>(JsonNode)ArtifactCore(id,path,r,true)).ToArray());});
    public override JsonObject Save(string id,string path,string content,JsonObject metadata,string? expectedRevision)=>Locked(()=>{if(path.StartsWith("originals/",StringComparison.Ordinal))throw new ProcessingException("IMPORT_ORIGINAL_IMMUTABLE");if(S(ProjectCore(id),"status")!="ACTIVE")throw new ProcessingException("PROJECT_ARCHIVED");if(Encoding.UTF8.GetByteCount(content)>2097152||metadata.ToJsonString().Length>65536||metadata.Any(p=>new[]{"status","validation","approved_by","released_by","revision","created_by"}.Contains(p.Key)))throw new ProcessingException("ARTIFACT_TOO_LARGE_OR_RESERVED_METADATA");JsonObject? old=null;if(Tree(Head()).ContainsKey(Storage(id,path)))old=ArtifactCore(id,path,Head());if(old?["revision"]?.GetValue<string>()!=expectedRevision)throw new ProcessingException("REVISION_CONFLICT");if(old?["metadata"]?["representation"]?.GetValue<string>()=="imported")throw new ProcessingException("FHIR_ORIGINAL_IMMUTABLE");if(old is not null&&S(old,"content")==content&&Data.Canonical(old["metadata"])==Data.Canonical(metadata))return old;Commit(new Dictionary<string,byte[]>{[Storage(id,path)]=Encoding.UTF8.GetBytes(content),[Meta(id,path)]=Encoding.UTF8.GetBytes(new JsonObject{["metadata"]=metadata.DeepClone()}.ToJsonString())},"Save model artifact "+path);return ArtifactCore(id,path,Head());},true);
    public override JsonObject Original(string id,string filename,byte[] bytes,JsonObject metadata,string? importId=null)=>Locked(()=>{if(bytes.Length>2097152||filename.Length is <1 or >128||filename.Any(c=>char.IsControl(c)||c is '/' or '\\' or '%'))throw new ProcessingException("IMPORT_FILENAME_OR_ID_INVALID");var hash=Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(bytes));var path="originals/"+(importId??hash)+"/"+filename;ArtifactPath(path);if(S(ProjectCore(id),"status")!="ACTIVE")throw new ProcessingException("PROJECT_ARCHIVED");if(Tree(Head()).ContainsKey(Storage(id,path))||Last(Head(),Storage(id,path))!="")throw new ProcessingException("IMPORT_ORIGINAL_EXISTS");Commit(new Dictionary<string,byte[]>{[Storage(id,path)]=bytes,[Meta(id,path)]=Encoding.UTF8.GetBytes(new JsonObject{["metadata"]=metadata.DeepClone()}.ToJsonString())},"Preserve imported model source");return ArtifactCore(id,path,Head());},true);
    public JsonObject Branch(string name,string baseRevision)=>Locked(()=>{BranchName(name);Reachable(baseRevision);if(Run(["rev-parse","--verify","refs/heads/"+name],check:false).Code==0)throw new ProcessingException("GIT_BRANCH_EXISTS");if(remote!="")Git("push","origin",baseRevision+":refs/heads/"+name);Git("update-ref","refs/heads/"+name,baseRevision,new string('0',40));return new JsonObject{["branch"]=name,["revision"]=baseRevision,["active_branch"]=branch,["switched"]=false};},true);
    public JsonObject Diff(string before,string after)=>Locked(()=>{Reachable(before);Reachable(after);return new JsonObject{["base_revision"]=before,["head_revision"]=after,["patch"]=Git("diff","--no-ext-diff","--no-textconv",before,after,"--")};});
    public JsonObject Info()=>Locked(()=>new JsonObject{["provider"]="git",["branch"]=branch,["revision"]=head,["capabilities"]=RepositoryOperations.Capabilities("git"),["remote_configured"]=remote!=""});
}
